<script setup>
import AppShell from '../../Components/Ui/AppShell.vue'
import { ref, computed } from 'vue'
import { router, useForm } from '@inertiajs/vue3'
const props = defineProps({ songs: Array, filters: Object })
const query = ref(props.filters?.q ?? '')
const modal = ref(false)
const form = useForm({ title: '', composer: '', author: '', copyright_notice: '', age_group: '', topics: '', notes: '', version_name: 'Standardfassung', lyrics: '', notation: '', chords: '', rights_status: 'unknown', rights_note: '', text_export_allowed: false, metadata_export_allowed: true, sheet: null })
const editorVersion = ref(null)
const editor = useForm({ name: '', language: 'de', parts: [], layout_data: { images: [] } })
const imageForm = useForm({ images: [] })
const canvas = { width: 420, height: 594 }
const activeImageId = ref(null)
const selectedImage = computed(() => editor.layout_data.images?.find(image => image.id === activeImageId.value) ?? null)
function search() { router.get('/lieder', { q: query.value }, { preserveState: true, replace: true }) }
function save() { form.post('/lieder', { forceFormData: true, onSuccess: () => { modal.value = false; form.reset() } }) }
function openEditor(version) { editorVersion.value = version; activeImageId.value = null; editor.defaults({ name: version.name, language: version.language ?? 'de', parts: (version.parts ?? []).map(part => ({ title: part.title ?? '', content: part.content, is_refrain: part.is_refrain })), layout_data: version.layout_data ?? { images: [] } }); editor.reset(); imageForm.reset() }
function saveEditor() { editor.put(`/lieder/fassungen/${editorVersion.value.id}`, { preserveScroll: true, onSuccess: () => { editorVersion.value = null } }) }
function uploadImages() { imageForm.post(`/lieder/fassungen/${editorVersion.value.id}/bilder`, { forceFormData: true, preserveScroll: true, onSuccess: () => window.location.reload() }) }
function generateSheet() { router.post(`/lieder/fassungen/${editorVersion.value.id}/liedblatt/erzeugen`, {}, { preserveScroll: true, onSuccess: () => { editorVersion.value = null } }) }
function addPart() { editor.parts.push({ title: '', content: '', is_refrain: false }) }
function addImage(image) { if (!editor.layout_data.images.some(item => item.id === image.id)) editor.layout_data.images.push({ id: image.id, x: 20, y: 20, width: 100, height: 100, rotation: 0, flipX: false, flipY: false }); activeImageId.value = image.id }
function moveImage(image, event) { image.x = Math.max(0, Math.min(canvas.width - image.width, event.offsetX - image.width / 2)); image.y = Math.max(0, Math.min(canvas.height - image.height, event.offsetY - image.height / 2)) }
function resizeImage(amount) { if (selectedImage.value) { selectedImage.value.width = Math.max(20, selectedImage.value.width + amount); selectedImage.value.height = Math.max(20, selectedImage.value.height + amount) } }
</script>
<template>
    <AppShell><template #toolbar><button class="btn btn-sm btn-primary" type="button" @click="modal = true"><i class="bi bi-plus-lg me-1"></i>Lied anlegen</button></template>
        <div class="container-full px-3 py-4"><h1 class="h2 mb-4">Liedersammlung</h1><form class="d-flex gap-2 mb-3" @submit.prevent="search"><input v-model="query" class="form-control" placeholder="Lieder durchsuchen"><button class="btn btn-outline-secondary">Suchen</button></form><div class="list-group"><div v-for="song in songs" :key="song.id" class="list-group-item"><strong>{{ song.title }}</strong><span class="small text-muted ms-2">{{ [song.author, song.composer].filter(Boolean).join(' · ') }}</span><div v-for="version in song.versions" :key="version.id" class="small mt-1 d-flex gap-2 align-items-center"><span>{{ version.name }} · Rechte: {{ version.rights_status }}</span><span v-if="version.sheet" class="text-success"><i class="bi bi-file-earmark-pdf"></i> Liedblatt vorhanden</span><button class="btn btn-sm btn-outline-secondary ms-auto" type="button" @click="openEditor(version)"><i class="bi bi-pencil"></i> Bearbeiten</button></div></div><p v-if="!songs.length" class="text-muted">Noch keine Lieder vorhanden.</p></div></div>
        <div v-if="modal" class="roo-modal-backdrop" @click.self="modal = false"><form class="roo-modal card" @submit.prevent="save"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5">Lied anlegen</h2><button type="button" class="btn-close" @click="modal = false"></button></div><label class="form-label">Titel</label><input v-model="form.title" class="form-control" required><div class="row g-2"><div class="col-md-6"><label class="form-label mt-2">Text:in</label><input v-model="form.author" class="form-control"></div><div class="col-md-6"><label class="form-label mt-2">Komponist:in</label><input v-model="form.composer" class="form-control"></div></div><label class="form-label mt-2">Fassung</label><input v-model="form.version_name" class="form-control" required><label class="form-label mt-2">Rechtestatus</label><select v-model="form.rights_status" class="form-select"><option value="unknown">Ungeklärt</option><option value="cleared">Geklärt</option><option value="restricted">Eingeschränkt</option><option value="licensed">Lizenziert</option></select><label class="form-label mt-2">Vorhandenes A5-Liedblatt (PDF)</label><input class="form-control" type="file" accept="application/pdf" @change="form.sheet = $event.target.files?.[0] ?? null"><button class="btn btn-primary mt-3" :disabled="form.processing">Speichern</button></div></form></div>
        <div v-if="editorVersion" class="roo-modal-backdrop" @click.self="editorVersion = null"><section class="roo-modal roo-modal-wide card"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5">Liedfassung bearbeiten</h2><button class="btn-close" type="button" @click="editorVersion = null"></button></div><div class="row g-4"><div class="col-lg-6"><label class="form-label">Fassungsname</label><input v-model="editor.name" class="form-control"><div class="d-flex justify-content-between align-items-center mt-3"><h3 class="h6 mb-0">Liedteile</h3><button class="btn btn-sm btn-outline-primary" type="button" @click="addPart">Teil hinzufügen</button></div><div v-for="(part, index) in editor.parts" :key="index" class="border rounded p-2 mt-2"><div class="d-flex gap-2"><input v-model="part.title" class="form-control" placeholder="Bezeichnung"><label class="form-check small mt-2 text-nowrap"><input v-model="part.is_refrain" class="form-check-input" type="checkbox"> Kehrvers</label></div><textarea v-model="part.content" class="form-control mt-2" rows="4" placeholder="Text"></textarea></div><label class="form-label mt-3">Bilder hinzufügen</label><input class="form-control" type="file" accept="image/*" multiple @change="imageForm.images = [...$event.target.files]"><button class="btn btn-sm btn-outline-secondary mt-2" type="button" @click="uploadImages">Bilder hochladen</button><div v-for="image in editorVersion.images" :key="image.id" class="small mt-2"><button class="btn btn-sm btn-outline-secondary" type="button" @click="addImage(image)">{{ image.original_name }} auf die Vorschau legen</button></div></div><div class="col-lg-6"><h3 class="h6">A5-Vorschau</h3><div class="song-canvas border bg-white position-relative" :style="{ width: canvas.width + 'px', height: canvas.height + 'px' }" @click="selectedImage && moveImage(selectedImage, $event)" @dragover.prevent @drop="selectedImage && moveImage(selectedImage, $event)"><div class="p-3"><h4>{{ editorVersion.song?.title }}</h4><section v-for="part in editor.parts" :key="part.title + part.content" :class="{ 'fw-bold border-start border-3 ps-2': part.is_refrain }"><strong v-if="part.title">{{ part.title }}</strong><div class="small text-pre-wrap">{{ part.content }}</div></section></div><img v-for="image in editor.layout_data.images" :key="image.id" :src="`/lieder/fassungen/${editorVersion.id}/bilder/${image.id}`" draggable="true" class="position-absolute" :class="{ 'border border-primary': activeImageId === image.id }" :style="{ left: image.x + 'px', top: image.y + 'px', width: image.width + 'px', height: image.height + 'px', transform: `rotate(${image.rotation}deg) scale(${image.flipX ? -1 : 1}, ${image.flipY ? -1 : 1})` }" @click.stop="activeImageId = image.id" @dragstart="activeImageId = image.id"></div><div class="d-flex gap-2 mt-2"><button v-if="selectedImage" class="btn btn-sm btn-outline-secondary" type="button" @click="selectedImage.rotation += 90">Drehen</button><button v-if="selectedImage" class="btn btn-sm btn-outline-secondary" type="button" @click="selectedImage.flipX = !selectedImage.flipX">Spiegeln</button><button v-if="selectedImage" class="btn btn-sm btn-outline-secondary" type="button" @click="resizeImage(20)">Größer</button><button v-if="selectedImage" class="btn btn-sm btn-outline-secondary" type="button" @click="resizeImage(-20)">Kleiner</button></div></div></div><div class="d-flex justify-content-end gap-2 mt-4"><button class="btn btn-outline-secondary" type="button" @click="editorVersion = null">Abbrechen</button><button class="btn btn-outline-primary" type="button" @click="generateSheet">A5-PDF erzeugen</button><button class="btn btn-primary" type="button" @click="saveEditor">Speichern</button></div></div></section></div>
    </AppShell>
</template>
